INSERT INTO public.scenario_spaces (id, version, name, definition, schema_version, created_at) VALUES ('warehouse_v1', '2b4d5a96d21a', 'Warehouse delivery - single injected pallet', '{"id": "warehouse_v1", "name": "Warehouse delivery - single injected pallet", "task": "tasks/warehouse_delivery_measured_v1.yaml", "parameters": [{"id": "robot.max_speed", "low": 0.1, "high": 0.5, "name": "Max linear speed", "type": "float", "unit": "m/s", "group": "robot", "prior": {"kind": "uniform"}, "enabled": true, "nominal": 0.26}, {"id": "obstacle.clearance", "low": 0.0, "high": 1.2, "name": "Obstacle lateral clearance", "type": "float", "unit": "m", "group": "task", "prior": {"kind": "uniform"}, "enabled": true, "nominal": 0.8}, {"id": "env.illuminance", "low": 5, "high": 1000, "name": "Ambient illuminance", "type": "float", "unit": "lux", "group": "environment", "prior": {"kind": "loguniform"}, "scale": "log", "enabled": true, "nominal": 300}, {"id": "sensor.lidar_noise_std", "low": 0.0, "high": 0.1, "name": "Lidar range noise (std)", "type": "float", "unit": "m", "group": "sensor", "prior": {"kind": "uniform"}, "enabled": true, "nominal": 0.01}, {"id": "env.floor_friction", "low": 0.1, "high": 1.0, "name": "Floor friction coefficient", "type": "float", "unit": "-", "group": "environment", "prior": {"kind": "uniform"}, "enabled": true, "nominal": 0.8}, {"id": "comms.cmd_delay_ms", "low": 0, "high": 400, "name": "Command delay", "type": "float", "unit": "ms", "group": "comms", "prior": {"kind": "uniform"}, "enabled": true, "nominal": 20}, {"id": "obstacle.along_path", "low": 0.2, "high": 0.8, "name": "Obstacle position along path", "type": "float", "unit": "-", "group": "task", "prior": {"kind": "uniform"}, "enabled": false, "nominal": 0.5}, {"id": "sensor.lidar_dropout", "low": 0.0, "high": 0.3, "name": "Lidar beam dropout probability", "type": "float", "unit": "probability", "group": "sensor", "prior": {"kind": "uniform"}, "enabled": false, "nominal": 0.0}], "constraints": [], "description": "TurtleBot 4 delivers from Dock A to Station B; a low pallet is injected near the nominal path.\n", "schema_version": 1, "oracle_thresholds": "default"}', 1, '2026-11-19 00:00:00.000000+00');
